r=Path(__file__).resolve().parents[2];out=r/'artifacts/replica/windows-download';js=(r/'docs/replica/source/original.js').read_text();raw=re.search(r'const categoryDefs=(\[.*?\]);',js).group(1);defs=json.loads(re.sub(r'(\w+):',r'"\1":',raw).replace("'",'"'));icons=dict(re.findall(r"(\w+):'([^']*)'",re.search(r'const icons=\{(.*?)\};',js).group(1)))
